CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'active',address_line1 text,city text,region text,postal_code text,country text,industry text,website text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clerk_user_id text NOT NULL UNIQUE,email text NOT NULL,display_name text,status text NOT NULL DEFAULT 'active',is_platform_admin boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'active',joined_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,user_id));
CREATE INDEX member_user_idx ON organization_members(user_id);
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL,scope text NOT NULL DEFAULT 'organization');
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,resource text NOT NULL,action text NOT NULL);
CREATE TABLE role_permissions(role_id uuid NOT NULL REFERENCES roles(id),permission_id uuid NOT NULL REFERENCES permissions(id),PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_member_id uuid NOT NULL REFERENCES organization_members(id),role_id uuid NOT NULL REFERENCES roles(id),assigned_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_member_id,role_id));
CREATE TABLE invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),email text NOT NULL,invited_by uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'pending',clerk_invitation_id text,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX invite_org_email_idx ON invitations(organization_id,email);
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid REFERENCES users(id),name text NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid REFERENCES users(id),employee_number text,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),customer_id uuid REFERENCES customers(id),name text NOT NULL,status text NOT NULL DEFAULT 'planned',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),employee_id uuid NOT NULL REFERENCES employees(id),assigned_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),customer_id uuid NOT NULL REFERENCES customers(id),order_number text NOT NULL,status text NOT NULL DEFAULT 'draft',total_amount numeric(12,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,order_number));
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),description text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price numeric(12,2) NOT NULL CHECK(unit_price>=0));
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),sender_user_id uuid REFERENCES users(id),recipient_user_id uuid REFERENCES users(id),channel text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE communication_preferences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),opt_in_email boolean NOT NULL DEFAULT false,opt_in_phone boolean NOT NULL DEFAULT false,opt_in_text boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,user_id));
CREATE TABLE communication_consent_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),preference_id uuid NOT NULL REFERENCES communication_preferences(id),channel text NOT NULL,previous_value boolean,new_value boolean NOT NULL,source text NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES organizations(id),actor_user_id uuid REFERENCES users(id),action text NOT NULL,resource_type text NOT NULL,resource_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org_date_idx ON audit_logs(organization_id,created_at DESC);
CREATE INDEX projects_org_idx ON projects(organization_id);
CREATE INDEX orders_org_customer_idx ON orders(organization_id,customer_id);
CREATE INDEX employees_org_idx ON employees(organization_id);
CREATE INDEX customers_org_idx ON customers(organization_id);
